{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "Brigatinib, the highest-transfer analogue (0.8649), has an estimated absolute oral bioavailability of 46% in healthy volunteers, directly supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Paliperidone, a structurally related fused-lactam piperidine, has an absolute oral bioavailability of 28% in healthy volunteers, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "LY2196044, which shares a pyridine/ether and basic amine motif with the query, showed an estimated absolute bioavailability of 45% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "UK-224,671, a high-transfer analogue (0.8573), had only 3.6% oral bioavailability in humans in the fed state, providing affirmative evidence for low F.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C37"],
      "claim": "Lurasidone, a high-transfer analogue (0.8309), has 10% oral bioavailability in the fasted state, below the 20% threshold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "SRT2104 had an absolute oral bioavailability of 13.8% in healthy volunteers, below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The strongest transferable evidence is mixed, but the highest-scoring analogue (brigatinib, 46% F) and multiple structurally relevant compounds (paliperidone 28%, LY2196044 45%) support F ≥20%. The low-F analogues carry specific liabilities—sulfamide, extensive first-pass metabolism, or poor solubility—that are not clearly present in the query. Therefore high oral bioavailability is better supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the query molecule.",
    "The highest-transfer analogues conflict in direction (brigatinib 46% vs UK-224,671 3.6–8%).",
    "Formulation-dependent bioavailability (e.g., paliperidone IR ~100% vs ER 28%) complicates translation to an unformulated query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

